  readonly rows = input.required<readonly Row[]>();
  readonly filter = signal('');
  readonly visibleRows = computed(() => filterRows(this.rows(), this.filter()));
}

private readonly _progress = signal<Record<string, TopicProgress>>({});
readonly progress = this._progress.asReadonly();

readonly completedCount = computed(() =>
  Object.values(this._progress()).filter(p => p.status === 'completed').length
);

readonly customerId = signal<string | null>(null);
readonly customer$ = toObservable(this.customerId).pipe(
  filter((id): id is string => !!id),
  switchMap(id => this.api.getCustomer(id))
);
readonly customer = toSignal(this.customer$, { initialValue: null });

